package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static unverified.ClonePairGenericInvocationTestSupport.*;

@Tag("timeout")
class ClonePair3930DifferenceFindingTest {

    private final ClonePair3930 subject = new ClonePair3930();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: no_termination.
     * Difference manifestation: the methods differ in whether they terminate.
     */
    @Test
    @BehavioralDifference(DifferenceType.NO_TERMINATION)
    void methodsDisagreeOnTermination() {
        InvocationOutcome method1Outcome = captureWithTimeout(values -> subject.method1((String) values[0], java.util.Arrays.copyOf((Object[]) values[1], ((Object[]) values[1]).length, String[].class), java.util.Arrays.copyOf((Object[]) values[2], ((Object[]) values[2]).length, String[].class)), 200L, "abcd", (Object) new String[]{"a", "b", "c", "d", "e"}, (Object) new String[]{"a", "b", "c", "d", "e"});
        InvocationOutcome method2Outcome = captureWithTimeout(values -> subject.method2((String) values[0], java.util.Arrays.copyOf((Object[]) values[1], ((Object[]) values[1]).length, String[].class), java.util.Arrays.copyOf((Object[]) values[2], ((Object[]) values[2]).length, String[].class)), 200L, "abcd", (Object) new String[]{"a", "b", "c", "d", "e"}, (Object) new String[]{"a", "b", "c", "d", "e"});

        assertEquals("OK", method2Outcome.status);
        assertEquals("TIMEOUT", method1Outcome.status);
    }
}
